package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.special.Erf;
import org.apache.commons.math3.exception.MathException;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.MathRuntimeException;
import org.apache.commons.math3.exception.MathServerException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NormalDistributionImpl#cumulativeProbability
 */
public class NormalDistributionImpl_cumulativeProbability_TriageGen5Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testCumulativeProbability_StandardNormal_MeanZero_SDOne() throws MathException {
        // Test case for Standard Normal Distribution (mean=0, sd=1)
        NormalDistributionImpl dist = new NormalDistributionImpl(0.0, 1.0);

        // P(X <= 0) should be 0.5
        Assert.assertEquals(0.5, dist.cumulativeProbability(0.0), DELTA);

        // P(X <= 1) approx 0.841344746
        Assert.assertEquals(0.8413447460685429, dist.cumulativeProbability(1.0), DELTA);

        // P(X <= -1) approx 0.158655253
        Assert.assertEquals(0.158655253931457, dist.cumulativeProbability(-1.0), DELTA);
    }

    @Test
    public void testCumulativeProbability_CustomMeanAndSD() throws MathException {
        // Test case for custom mean=5.0, sd=2.0
        NormalDistributionImpl dist = new NormalDistributionImpl(5.0, 2.0);

        // P(X <= 5) should be 0.5
        Assert.assertEquals(0.5, dist.cumulativeProbability(5.0), DELTA);

        // P(X <= 7) is same as P(Z <= 1)
        Assert.assertEquals(0.8413447460685429, dist.cumulativeProbability(7.0), DELTA);
    }

    @Test
    public void testCumulativeProbability_ExtremeValues() throws MathException {
        NormalDistributionImpl dist = new NormalDistributionImpl(0.0, 1.0);

        // Large positive value should approach 1.0
        Assert.assertEquals(1.0, dist.cumulativeProbability(10.0), DELTA);

        // Large negative value should approach 0.0
        Assert.assertEquals(0.0, dist.cumulativeProbability(-10.0), DELTA);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testCumulativeProbability_InvalidStandardDeviation_Zero() throws MathException {
        // Standard deviation must be positive. 
        // Note: Depending on the implementation of the constructor, this might throw during construction
        // or during the method call if division by zero occurs.
        new NormalDistributionImpl(0.0, 0.0);
        // If constructor allows it, the method call will trigger division by zero/NaN
        new NormalDistributionImpl(0.0, 0.0).cumulativeProbability(1.0);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testCumulativeProbability_InvalidStandardDeviation_Negative() throws MathException {
        new NormalDistributionImpl(0.0, -1.0).cumulativeProbability(1.0);
    }

    @Test
    public void testCumulativeProbability_Setters() throws MathException {
        NormalDistributionImpl dist = new NormalDistributionImpl();
        dist.setMean(10.0);
        dist.setStandardDeviation(5.0);

        Assert.assertEquals(10.0, dist.getMean(), DELTA);
        Assert.assertEquals(5.0, dist.getStandardDeviation(), DELTA);

        // P(X <= 10) with mean 10 should be 0.5
        Assert.assertEquals(0.5, dist.cumulativeProbability(10.0), DELTA);
    }
}
